let ship, bullets, rocks;
let lives = 3;
let gameOver = false; // CONVERTED: world.timeScale does not exist, so this flag freezes the game

function setup() {
  new Canvas(500, 500);
  ship = new Sprite(250, 250, 30, 'none');
  ship.image = '🚀';

  bullets = new Group();
  bullets.diameter = 6;
  bullets.color = 'yellow';
  bullets.life = 60;
  bullets.collider = 'none'; // CONVERTED: bullets.overlaps(rocks) used to make them pass through each other

  rocks = new Group();
  rocks.diameter = 40;
  rocks.color = 'gray';

  // CONVERTED: camera.zoom does not exist in moSHion, so the view stays at 1x
}

function hit(b, r) {
  b.remove();
  r.remove();
}

function update() {
  if (gameOver) return; // CONVERTED: replaces world.timeScale = 0

  bullets.overlaps(rocks, hit); // CONVERTED: touching is asked every frame in update()

  ship.rotateTowards(mouse, 0.2); // CONVERTED: the third "facing" argument does not exist

  if (frameCount % 60 == 0) {
    let r = new rocks.Sprite(random(width), -20);
    r.vel.y = random(1, 3);
  }
  rocks.cull(50);

  if (ship.overlaps(rocks)) {
    lives--;
    rocks.delete(); // CONVERTED: rocks.removeAll() is group.delete()
  }

  if (mouse.presses()) { // CONVERTED: mousePressed() moved into update()
    let b = new bullets.Sprite(ship.x, ship.y);
    b.direction = ship.rotation;
    b.speed = 8;
  }

  if (lives <= 0) {
    gameOver = true;
  }
}

function draw() {
  background(10);
}

function drawTop() {
  fill(255);
  text('Lives: ' + lives, 10, 20);
  if (lives <= 0) {
    textSize(40);
    text('GAME OVER', 130, 250);
  }
}
